<?php declare(strict_types=1);require_once __DIR__.'/_common.php';if(post()){verifyCsrf();$id=(int)$_POST['id'];$status=$_POST['status']??'';$note=clean('note',3000);if(in_array($status,['approved','rejected'],true)){$s=db()->prepare('SELECT user_id FROM membership_applications WHERE id=?');$s->execute([$id]);$app=$s->fetch();if($app){$newRole=$status==='approved'?'member':'user';db()->prepare('UPDATE membership_applications SET status=?,reviewed_by=?,reviewed_at=NOW(),admin_note=? WHERE id=?')->execute([$status,$admin['id'],$note,$id]);if($status==='approved')db()->prepare('UPDATE users SET role="member",email_verified=1,is_active=1,is_banned=0 WHERE id=?')->execute([$app['user_id']]);adminAudit('membership_'.$status,'membership_application',$id,['user_id'=>$app['user_id']]);flash('success','Membership application reviewed.');}}redirect('memberships.php');}$rows=db()->query("SELECT a.*,u.full_name,u.email FROM membership_applications a JOIN users u ON u.id=a.user_id ORDER BY FIELD(a.status,'pending','approved','rejected'),a.created_at DESC")->fetchAll();$pageTitle='Membership applications';require dirname(__DIR__).'/includes/header.php';?><section class="section"><div class="container"><p class="eyebrow">Member onboarding</p><h1 class="section-title">Membership applications.</h1><div class="table-wrap" style="margin-top:30px"><table><thead><tr><th>Applicant</th><th>Motivation</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $a):?><tr id="application-<?=$a['id']?>"><td><?=e($a['full_name'])?><br><?=e($a['email'])?></td><td style="white-space:normal;min-width:320px"><?=e($a['motivation'])?></td><td><span class="status-chip status-<?=e($a['status'])?>"><?=e(ucfirst($a['status']))?></span></td><td><?php if($a['status']==='pending'):?><form method="post" class="admin-actions"><?=csrfField()?><input type="hidden" name="id" value="<?=$a['id']?>"><input name="note" placeholder="Admin note"><button class="btn primary" name="status" value="approved">Approve member</button><button class="btn coral" name="status" value="rejected">Reject</button></form><?php else:?>Reviewed <?=e($a['reviewed_at'])?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></section><?php require dirname(__DIR__).'/includes/footer.php';
